CREATE TEMP TABLE stage_events (
  qid text PRIMARY KEY, title text, summary text,
  start_year int, start_month smallint, start_day smallint,
  end_year int, end_month smallint, end_day smallint,
  precision date_precision, display_date text, importance smallint, url text,
  event_id bigint
) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q580640', '2006 Nuku‘alofa riots', 'The 2006 Nukuʻalofa riots, also known as the 2006 Tongan riots, started on 16 November, in the Tongan capital of Nukuʻalofa. The Legislative Assembly of Tonga was due to adjourn for the year and despite promises of action, had done little to advance democracy in the government.', 2006, 11, 16, NULL, NULL, NULL, 'day', '16 November 2006', 41, 'https://en.wikipedia.org/wiki/2006_Nuku%CA%BBalofa_riots'),
